-- Extensión compatible: tareas personales y proyección recuperable de eventos existentes.
CREATE TABLE institution_task(id VARCHAR(36) PRIMARY KEY,creator_id VARCHAR(64) NOT NULL,responsible_id VARCHAR(64) NOT NULL,title VARCHAR(180) NOT NULL,description_text TEXT NOT NULL,created_ms BIGINT NOT NULL,reminder_ms BIGINT,execution_from_ms BIGINT,execution_until_ms BIGINT,deadline_ms BIGINT,priority_code VARCHAR(12) NOT NULL,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,resource_type VARCHAR(24) NOT NULL,resource_id VARCHAR(36) NOT NULL,completed_ms BIGINT,completed_by VARCHAR(64),manual_confirmed BOOLEAN NOT NULL,FOREIGN KEY(creator_id) REFERENCES staff_account(actor_id),FOREIGN KEY(responsible_id) REFERENCES staff_account(actor_id),FOREIGN KEY(completed_by) REFERENCES core_actor(id),CHECK(creator_id=responsible_id),CHECK(state IN ('PENDIENTE','EN_CURSO','COMPLETADA','CANCELADA')),CHECK(priority_code IN ('BAJA','NORMAL','ALTA')),FOREIGN KEY(resource_id) REFERENCES core_case(id),CHECK(resource_type='CASO'),CHECK(execution_until_ms IS NULL OR execution_from_ms IS NOT NULL AND execution_until_ms>execution_from_ms),CHECK((state='COMPLETADA' AND completed_ms IS NOT NULL AND completed_by IS NOT NULL AND manual_confirmed=TRUE) OR (state<>'COMPLETADA' AND completed_ms IS NULL AND completed_by IS NULL AND manual_confirmed=FALSE)));
CREATE INDEX ix_task_owner ON institution_task(responsible_id,state,created_ms);
CREATE TABLE task_history(seq BIGINT AUTO_INCREMENT PRIMARY KEY,task_id VARCHAR(36) NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,revision BIGINT NOT NULL,event_code VARCHAR(32) NOT NULL,snapshot_doc TEXT NOT NULL,FOREIGN KEY(task_id) REFERENCES institution_task(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id));
CREATE TABLE task_command(id VARCHAR(36) PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,action_code VARCHAR(24) NOT NULL,request_hash CHAR(64) NOT NULL,task_id VARCHAR(36) NOT NULL,result_revision BIGINT NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(task_id) REFERENCES institution_task(id));
CREATE TABLE workflow_event(seq BIGINT AUTO_INCREMENT PRIMARY KEY,event_key VARCHAR(100) NOT NULL UNIQUE,code VARCHAR(48) NOT NULL,resource_type VARCHAR(24) NOT NULL,resource_id VARCHAR(36) NOT NULL,at_ms BIGINT NOT NULL);
CREATE TABLE notification_source(stream_code VARCHAR(16) NOT NULL,event_key VARCHAR(100) NOT NULL,processed_ms BIGINT NOT NULL,outcome VARCHAR(32) NOT NULL,PRIMARY KEY(stream_code,event_key));
-- No reenviar retrospectivamente avisos previos a la activación.
INSERT INTO notification_source SELECT 'CORE',CONCAT('',seq),at_ms,'BASELINE_PREVIO' FROM core_event;
INSERT INTO notification_source SELECT 'RECEPCION',CONCAT('',seq),at_ms,'BASELINE_PREVIO' FROM operational_event;
CREATE TABLE institution_notification(seq BIGINT AUTO_INCREMENT PRIMARY KEY,id VARCHAR(36) NOT NULL UNIQUE,stream_code VARCHAR(16) NOT NULL,event_key VARCHAR(100) NOT NULL,recipient_id VARCHAR(64) NOT NULL,category VARCHAR(48) NOT NULL,resource_type VARCHAR(24) NOT NULL,resource_id VARCHAR(36) NOT NULL,created_ms BIGINT NOT NULL,read_ms BIGINT,UNIQUE(stream_code,event_key,recipient_id,category,resource_id),FOREIGN KEY(recipient_id) REFERENCES staff_account(actor_id));
CREATE INDEX ix_notification_owner ON institution_notification(recipient_id,seq,read_ms);
CREATE TABLE notification_outbox(notification_id VARCHAR(36) PRIMARY KEY,correlation_id VARCHAR(36) NOT NULL UNIQUE,state VARCHAR(32) NOT NULL,human_state VARCHAR(40) NOT NULL,attempt_count INT NOT NULL,next_attempt_ms BIGINT NOT NULL,claim_id VARCHAR(36),lease_until BIGINT,confirmed_ms BIGINT,confirmed_by VARCHAR(64),FOREIGN KEY(notification_id) REFERENCES institution_notification(id),FOREIGN KEY(confirmed_by) REFERENCES core_actor(id));
CREATE TABLE mail_attempt(id VARCHAR(36) PRIMARY KEY,notification_id VARCHAR(36) NOT NULL,recipient_id VARCHAR(64) NOT NULL,resolved_email VARCHAR(180) NOT NULL,started_ms BIGINT NOT NULL,finished_ms BIGINT,state VARCHAR(32) NOT NULL,stage_code VARCHAR(16) NOT NULL,http_status INT,remote_request_id VARCHAR(36),FOREIGN KEY(notification_id) REFERENCES notification_outbox(notification_id),FOREIGN KEY(recipient_id) REFERENCES staff_account(actor_id));
CREATE TABLE mail_campaign(id VARCHAR(64) PRIMARY KEY,sends_started INT NOT NULL,maximum_sends INT NOT NULL,CHECK(maximum_sends BETWEEN 1 AND 4),CHECK(sends_started BETWEEN 0 AND maximum_sends));
CREATE TABLE notification_guard(id INT PRIMARY KEY);
INSERT INTO notification_guard VALUES(1);
